# ---- development/runtime.py ----
"""Observation and action normalization helpers."""

_LAST_STEP = [-1, -1]

def _get(value, key, default=None):
    if isinstance(value, dict):
        return value.get(key, default)
    getter = getattr(value, "get", None)
    if callable(getter):
        return getter(key, default)
    return getattr(value, key, default)


def _regime(configuration):
    interval = int(_get(configuration, "townCenterSellInterval", 12) or 12)
    return "rebalance" if interval >= 24 else "legacy"


def _copy_action(action):
    action = action if isinstance(action, dict) else {}
    return {
        "farmer": list(action.get("farmer") or ["PASS"]),
        "hands": [list(order or ["PASS"]) for order in (action.get("hands") or [])],
        "market": [list(order) for order in (action.get("market") or [])],
    }


def _runtime_context(obs, last_route_step):
    if isinstance(obs, dict):
        step = min(max(0, int(obs.get("step", 0) or 0)), last_route_step)
        seat = 1 if int(obs.get("player", 0) or 0) == 1 else 0
        farms = obs.get("farms", []) or []
    else:
        step = min(max(0, int(_get(obs, "step", 0) or 0)), last_route_step)
        seat = _seat(obs)
        farms = _get(obs, "farms", []) or []
    farm = farms[seat] if seat < len(farms) else {}
    hands = farm.get("hands", []) if isinstance(farm, dict) else (_get(farm, "hands", []) or [])
    reset = step == 0 or step < _LAST_STEP[seat]
    _LAST_STEP[seat] = step
    return step, seat, farm, len(hands or []), reset


def _project_action(action, expected_hands):
    """Final schema/alignment boundary; valid materialized actions pass through."""
    if isinstance(action, dict):
        farmer = action.get("farmer")
        hands = action.get("hands")
        market = action.get("market")
        if (
            isinstance(farmer, list)
            and isinstance(hands, list)
            and len(hands) == expected_hands
            and all(isinstance(order, list) and order for order in hands)
            and isinstance(market, list)
            and all(isinstance(order, list) for order in market)
        ):
            return action
    action = _copy_action(action)
    hands = action["hands"]
    if len(hands) < expected_hands:
        hands.extend([["PASS"] for _ in range(expected_hands - len(hands))])
    action["hands"] = hands[:expected_hands]
    return action


def _project_atomic_plants(obs, action):
    """Mirror the engine's same-crop atomic PLANT cancellation when observable."""
    private = _get(obs, "private", None)
    if private is None:
        return action
    seeds = _get(private, "seeds", None)
    if seeds is None:
        return action
    farmer = action.get("farmer") if isinstance(action, dict) else None
    hands = action.get("hands") if isinstance(action, dict) else None
    if not isinstance(farmer, list) or not isinstance(hands, list):
        return action
    units = [farmer, *hands]
    demand = {}
    for order in units:
        if isinstance(order, list) and len(order) >= 2 and order[0] == "PLANT":
            crop = str(order[1])
            demand[crop] = demand.get(crop, 0) + 1
    if not demand:
        return action
    available = {}
    for crop in demand:
        raw = _get(seeds, crop, None)
        if raw is None:
            return action
        try:
            available[crop] = max(0, int(raw))
        except (TypeError, ValueError):
            return action
    blocked = {crop for crop, count in demand.items() if count > available[crop]}
    if not blocked:
        return action
    projected = _copy_action(action)
    projected_units = [projected["farmer"], *projected["hands"]]
    projected_units = [
        ["PASS"]
        if isinstance(order, list)
        and len(order) >= 2
        and order[0] == "PLANT"
        and str(order[1]) in blocked
        else order
        for order in projected_units
    ]
    projected["farmer"] = projected_units[0]
    projected["hands"] = projected_units[1:]
    return projected


def _seat(obs):
    return 1 if int(_get(obs, "player", 0) or 0) == 1 else 0


def _farm(obs, seat):
    farms = list(_get(obs, "farms", []) or [])
    return farms[seat] if seat < len(farms) else {}


def _align_hands(action, obs):
    expected = len(_get(_farm(obs, _seat(obs)), "hands", []) or [])
    return _project_action(action, expected)


def _tile_at(farm, position):
    try:
        x, y = int(position[0]), int(position[1])
        return (_get(farm, "tiles", []) or [])[y][x]
    except (IndexError, TypeError, ValueError):
        return "LOCKED"


def _trace_actor_action(actions, step, actor):
    trace = actions[min(max(int(step), 0), len(actions) - 1)] or {}
    if actor == "farmer":
        return list(trace.get("farmer") or ["PASS"])
    hands = trace.get("hands", []) or []
    return list(hands[actor] if actor < len(hands) else ["PASS"])

# ---- development/weed_repair.py ----
"""Actor-local bounded weed repair."""


_WEED_STATE = {0: {}, 1: {}}
_WEED_REPLAY_STEPS = 8


def _weed_reset(seat):
    game = {"active": {}}
    _WEED_STATE[seat] = game
    return game


def _weed_needs_repair(farm, action, game, route_candidate=True):
    if game["active"]:
        return True
    if not route_candidate:
        return False
    positions = [_get(farm, "farmer"), *list(_get(farm, "hands", []) or [])]
    unit_actions = [action.get("farmer", ["PASS"]), *list(action.get("hands") or [])]
    for position, intended in zip(positions, unit_actions):
        if not isinstance(intended, list) or not intended or intended[0] not in ("BUILD_PASTURE", "PLANT"):
            continue
        tile = _tile_at(farm, position)
        if isinstance(tile, dict) and tile.get("kind") == "WEED":
            return True
    return False


def _weed_repair_action(action, actions, step, farm, game):
    positions = [_get(farm, "farmer"), *list(_get(farm, "hands", []) or [])]
    unit_actions = [action.get("farmer", ["PASS"]), *list(action.get("hands") or [])]
    active = game["active"]

    for actor, transaction in list(active.items()):
        index = 0 if actor == "farmer" else int(actor) + 1
        if index >= len(unit_actions):
            active.pop(actor, None)
            continue
        age = step - transaction["start"]
        if age == 1:
            unit_actions[index] = list(transaction["intended"])
        elif 2 <= age <= 1 + _WEED_REPLAY_STEPS:
            unit_actions[index] = _trace_actor_action(actions, step - 1, actor)
        else:
            active.pop(actor, None)

    for index, (position, intended) in enumerate(zip(positions, unit_actions)):
        actor = "farmer" if index == 0 else index - 1
        if actor in active or not isinstance(intended, list) or not intended:
            continue
        if intended[0] not in ("BUILD_PASTURE", "PLANT"):
            continue
        tile = _tile_at(farm, position)
        if not isinstance(tile, dict) or tile.get("kind") != "WEED":
            continue
        active[actor] = {"start": step, "intended": list(intended)}
        unit_actions[index] = ["DIG"]

    action["farmer"] = unit_actions[0] if unit_actions else ["PASS"]
    action["hands"] = unit_actions[1:]
    return action

# ---- development/market.py ----
"""Exact price impact and route-existing SELL-slot ranking."""

import math


def _shape(name, value):
    value = max(0.0, float(value))
    if name == "linear":
        return value
    if name == "sq":
        return value * value
    if name == "sqrt":
        return math.sqrt(value)
    if name == "log":
        return math.log1p(value)
    if name == "log10":
        return math.log10(1.0 + value)
    raise ValueError(name)


def _market_price(item, inventory):
    base, equilibrium, scale, below_func, below_target, above_func, above_target = (
        _MARKET_PARAMS[item]
    )
    if inventory < equilibrium:
        amplitude = below_target * base / _shape(below_func, scale)
        price = base + amplitude * _shape(below_func, equilibrium - inventory)
    else:
        amplitude = above_target * base / _shape(above_func, scale)
        price = base - amplitude * _shape(above_func, inventory - equilibrium)
    return max(_PRICE_FLOOR, int(round(price)))


def _is_sell(order):
    return (
        isinstance(order, (list, tuple))
        and len(order) >= 3
        and order[0] == "SELL"
        and order[1] in _MARKET_PARAMS
    )


def _has_multiple_sells(action):
    found = 0
    for order in action.get("market", []) or []:
        if _is_sell(order):
            found += 1
            if found >= 2:
                return True
    return False


def _impact_score(obs, order):
    if not _is_sell(order):
        return float("-inf")
    item = str(order[1])
    try:
        quantity = max(0, int(order[2]))
    except (TypeError, ValueError):
        return 0.0
    market = _get(obs, "market", {}) or {}
    inventory = _get(market, "inventory", {}) or {}
    prices = _get(market, "prices", {}) or {}
    current_inventory = int(_get(inventory, item, 10000) or 0)
    current_quote = float(
        _get(prices, item, _market_price(item, current_inventory)) or 0
    )
    later_quote = float(_market_price(item, current_inventory + quantity))
    return float(quantity) * max(0.0, current_quote - later_quote)


def _demand_per_day(obs, configuration, item):
    town = _get(obs, "town", {}) or {}
    shops = list(_get(town, "unlocked_shops", []) or [])
    turns_per_day = int(_get(configuration, "turnsPerDay", 24) or 24)
    shop_interval = max(
        1, int(_get(configuration, "townShopSellInterval", 4) or 4)
    )
    demand = 0.0
    for shop in shops:
        products = _SHOP_PRODUCTS.get(shop, ())
        if item in products:
            demand += (turns_per_day / shop_interval) * (
                2 if len(products) == 1 else 1
            )
    regime = _regime(configuration)
    if item != "FERTILIZER":
        center_default = 24 if regime == "rebalance" else 12
        center_interval = max(
            1,
            int(
                _get(configuration, "townCenterSellInterval", center_default)
                or center_default
            ),
        )
        day = int(_get(obs, "day", int(_get(obs, "step", 0) or 0) // 24) or 0)
        multiplier = (
            1
            if regime == "rebalance"
            else (4 if day >= 20 else 2 if day >= 10 else 1)
        )
        demand += (turns_per_day / center_interval) * multiplier
    return demand


def _order_score(obs, configuration, order):
    score = _impact_score(obs, order)
    if _regime(configuration) != "rebalance" or score <= 0 or not _is_sell(order):
        return score
    item = str(order[1])
    quantity = max(0, int(order[2]))
    market = _get(obs, "market", {}) or {}
    inventory = _get(market, "inventory", {}) or {}
    current_inventory = int(_get(inventory, item, 10000) or 0)
    demand = max(0.25, _demand_per_day(obs, configuration, item))
    excess = max(0.0, current_inventory + quantity - 10000)
    urgency = min(1.0, (excess / demand) / 10.0)
    return score * (1.0 + _DEMAND_ALPHA * urgency)


def _rank_sell_slots(obs, action, configuration):
    market = list(action.get("market") or [])
    rows = [
        (_order_score(obs, configuration, order), -index, list(order))
        for index, order in enumerate(market)
        if _is_sell(order)
    ]
    if len(rows) < 2:
        return action
    rows.sort(reverse=True)
    ranked = iter(row[2] for row in rows)
    action["market"] = [next(ranked) if _is_sell(order) else order for order in market]
    return action

# ---- development/agent.py ----
"""v27 development entrypoint."""


def agent(obs, configuration=None):
    try:
        actions = _REBALANCE_ACTIONS
        step, seat, farm, expected_hands, reset = _runtime_context(obs, len(actions) - 1)
        game = _weed_reset(seat) if reset else _WEED_STATE[seat]
        template = actions[step]
        aligned = _ROUTE_HAND_COUNTS[step] == expected_hands
        weed = _weed_needs_repair(farm, template, game, step in _WEED_CANDIDATE_STEPS)
        if (
            aligned
            and not weed
            and step not in _MULTI_SELL_STEPS
        ):
            return _project_atomic_plants(obs, template)
        action = _copy_action(template)
        if weed:
            _weed_repair_action(action, actions, step, farm, game)
        if step in _MULTI_SELL_STEPS:
            _rank_sell_slots(obs, action, configuration)
        action = _project_atomic_plants(obs, action)
        return _project_action(action, expected_hands)
    except Exception:
        farms = _get(obs, "farms", []) or []
        seat = 1 if int(_get(obs, "player", 0) or 0) == 1 else 0
        farm = farms[seat] if seat < len(farms) else {}
        return {
            "farmer": ["PASS"],
            "hands": [["PASS"] for _ in (_get(farm, "hands", []) or [])],
            "market": [],
        }


def _kaggle_submission_entrypoint(obs, configuration=None):
    return agent(obs, configuration)

